-- T119: every settlement of Serbia, grouped by upravni okrug (Beograd is its
-- own region), with the municipality each belongs to. Source: the sr.wikipedia
-- list "Spisak naselja u Srbiji" (it follows the RZS register; Kosovo i
-- Metohija included), the names transliterated to Latin and checked against
-- the urosran gist "srbija-svi-gradovi.json", which also adds 25 post-office places
-- the register lacks (spas, holiday places). Towns split into "(varoš)" and
-- "(selo)" keep the town under its plain name. A name shared by several places
-- gets the municipality in its slug, except the town among villages.
--
-- The 27 cities that already exist keep their id, name, locative and listings
-- and only move to their okrug; their listings follow. The seven broad regions
-- of the old seed go once they hold no city. Run by hand on the server, like
-- every migration since the production compose (no migrate at start).

