ON CONFLICT ("slug") DO UPDATE
SET "regionId" = EXCLUDED."regionId", "municipality" = EXCLUDED."municipality", "kind" = EXCLUDED."kind";

-- Headings put a city into a sentence ("Stanovi u Šapcu"); the old seed's
-- cities had their locative, a new database gets it here.
UPDATE "City" c SET "nameLocative" = v."locative"
FROM (VALUES
  ('beograd', 'Beogradu'),
  ('novi-sad', 'Novom Sadu'),
  ('subotica', 'Subotici'),
  ('zrenjanin', 'Zrenjaninu'),
  ('pancevo', 'Pančevu'),
  ('sombor', 'Somboru'),
  ('kikinda', 'Kikindi'),
  ('sremska-mitrovica', 'Sremskoj Mitrovici'),
  ('kragujevac', 'Kragujevcu'),
  ('krusevac', 'Kruševcu'),
  ('jagodina', 'Jagodini'),
  ('cacak', 'Čačku'),
  ('gornji-milanovac', 'Gornjem Milanovcu'),
  ('uzice', 'Užicu'),
  ('valjevo', 'Valjevu'),
  ('sabac', 'Šapcu'),
  ('loznica', 'Loznici'),
  ('zajecar', 'Zaječaru'),
  ('bor', 'Boru'),
  ('negotin', 'Negotinu'),
  ('kladovo', 'Kladovu'),
  ('nis', 'Nišu'),
  ('leskovac', 'Leskovcu'),
  ('vranje', 'Vranju'),
  ('pirot', 'Pirotu'),
  ('prokuplje', 'Prokuplju'),
  ('kosovska-mitrovica', 'Kosovskoj Mitrovici')
) AS v("slug", "locative")
WHERE c."slug" = v."slug" AND c."nameLocative" IS NULL;

INSERT INTO "CityArea" ("id", "cityId", "name", "slug")
SELECT gen_random_uuid(), c."id", v."name", v."slug"
FROM (VALUES
  ('beograd', 'Vračar', 'vracar'),
  ('beograd', 'Novi Beograd', 'novi-beograd'),
  ('beograd', 'Zemun', 'zemun'),
  ('beograd', 'Stari Grad', 'stari-grad'),
  ('beograd', 'Savski Venac', 'savski-venac'),
  ('beograd', 'Voždovac', 'vozdovac'),
  ('beograd', 'Zvezdara', 'zvezdara'),
  ('beograd', 'Palilula', 'palilula'),
  ('beograd', 'Čukarica', 'cukarica'),
  ('beograd', 'Rakovica', 'rakovica'),
  ('novi-sad', 'Stari Grad', 'stari-grad'),
  ('novi-sad', 'Liman', 'liman'),
  ('novi-sad', 'Grbavica', 'grbavica'),
  ('novi-sad', 'Detelinara', 'detelinara'),
  ('novi-sad', 'Podbara', 'podbara'),
  ('novi-sad', 'Petrovaradin', 'petrovaradin')
) AS v("city", "name", "slug")
JOIN "City" c ON c."slug" = v."city"
ON CONFLICT ("cityId", "slug") DO NOTHING;

-- A listing's region is its city's.
UPDATE "Listing" l SET "regionId" = c."regionId"
FROM "City" c
WHERE l."cityId" = c."id" AND l."regionId" IS DISTINCT FROM c."regionId";

-- A draft with a region and no city yet picks again.
UPDATE "Listing" SET "regionId" = NULL
WHERE "cityId" IS NULL
  AND "regionId" IN (SELECT "id" FROM "Region" WHERE "slug" IN ('vojvodina', 'sumadija', 'zapadna-srbija', 'istocna-srbija', 'juzna-srbija', 'kosovo'));

DELETE FROM "Region" r
WHERE r."slug" IN ('vojvodina', 'sumadija', 'zapadna-srbija', 'istocna-srbija', 'juzna-srbija', 'kosovo')
  AND NOT EXISTS (SELECT 1 FROM "City" c WHERE c."regionId" = r."id");
